style.css:
/* SHADOW//RONIN — Roblox */

:root {
  /* swap these values to change the palette */
  --my-bg: #08090d;
  --my-surface: #11131a;
  --my-surface-2: #191c25;
  --my-red: #a31327;
  --my-red-glow: #e0203d;
  --my-text: #e5e5eb;
  --my-muted: #858895;
}

/* dark background and typography */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: "Arial", sans-serif !important;
}

/* stealthy links */
a {
  color: var(--my-text) !important;
  transition: color 0.2s ease !important;
}

a:hover {
  color: var(--my-red-glow) !important;
}

/* dark controls */
button,
input,
textarea,
select {
  background: var(--my-surface-2) !important;
  color: var(--my-text) !important;
  border: 1px solid #292d38 !important;
  border-radius: 8px !important;
}

/* subtle image rounding */
img {
  border-radius: 6px !important;
}
